import React, { useState, useEffect } from 'react';
import { useDispatch, useSelector } from 'react-redux';
import { useNavigate } from 'react-router-dom';
import {
  Box,
  Container,
  Card,
  CardContent,
  Typography,
  Button,
  AppBar,
  Toolbar,
  IconButton,
  List,
  ListItem,
  ListItemText,
  ListItemSecondaryAction,
  Dialog,
  DialogTitle,
  DialogContent,
  DialogActions,
  TextField,
  MenuItem,
  Fab,
  Avatar,
  Chip,
} from '@mui/material';
import {
  ArrowBack,
  Add,
  Edit,
  Delete,
  Phone,
  Person,
} from '@mui/icons-material';

import {
  addEmergencyContact,
  updateEmergencyContact,
  deleteEmergencyContact,
} from '../store/slices/userSlice';

const relationships = ['Family', 'Friend', 'Colleague', 'Other'];

const EmergencyContacts = () => {
  const dispatch = useDispatch();
  const navigate = useNavigate();

  const { user } = useSelector((state) => state.auth);
  const { isLoading } = useSelector((state) => state.user);

  const [contacts, setContacts] = useState([]);
  const [dialogOpen, setDialogOpen] = useState(false);
  const [deleteDialog, setDeleteDialog] = useState(false);
  const [editingContact, setEditingContact] = useState(null);
  const [contactToDelete, setContactToDelete] = useState(null);

  const [formData, setFormData] = useState({
    name: '',
    phone: '',
    relationship: 'Family',
  });

  useEffect(() => {
    if (user?.emergencyContacts) {
      setContacts(user.emergencyContacts);
    }
  }, [user]);

  const handleInputChange = (e) => {
    setFormData({
      ...formData,
      [e.target.name]: e.target.value,
    });
  };

  const handleAddContact = () => {
    setEditingContact(null);
    setFormData({
      name: '',
      phone: '',
      relationship: 'Family',
    });
    setDialogOpen(true);
  };

  const handleEditContact = (contact) => {
    setEditingContact(contact);
    setFormData({
      name: contact.name,
      phone: contact.phone,
      relationship: contact.relationship,
    });
    setDialogOpen(true);
  };

  const handleDeleteContact = (contact) => {
    setContactToDelete(contact);
    setDeleteDialog(true);
  };

  const handleSubmit = async () => {
    if (!formData.name.trim() || !formData.phone.trim()) {
      return;
    }

    // Add country code if not present
    let phone = formData.phone.trim();
    if (!phone.startsWith('+')) {
      phone = '+1' + phone.replace(/\D/g, '');
    }

    const contactData = {
      name: formData.name.trim(),
      phone,
      relationship: formData.relationship,
    };

    try {
      if (editingContact) {
        await dispatch(updateEmergencyContact({
          contactId: editingContact._id,
          contactData,
        }));
      } else {
        await dispatch(addEmergencyContact(contactData));
      }
      setDialogOpen(false);
    } catch (error) {
      console.error('Failed to save contact:', error);
    }
  };

  const confirmDelete = async () => {
    if (contactToDelete) {
      try {
        await dispatch(deleteEmergencyContact(contactToDelete._id));
        setDeleteDialog(false);
        setContactToDelete(null);
      } catch (error) {
        console.error('Failed to delete contact:', error);
      }
    }
  };

  const getRelationshipColor = (relationship) => {
    const colors = {
      Family: 'primary',
      Friend: 'secondary',
      Colleague: 'info',
      Other: 'default',
    };
    return colors[relationship] || 'default';
  };

  return (
    <Box>
      {/* Header */}
      <AppBar position="static" elevation={1}>
        <Toolbar>
          <IconButton
            edge="start"
            color="inherit"
            onClick={() => navigate('/dashboard')}
          >
            <ArrowBack />
          </IconButton>
          <Typography variant="h6" sx={{ flexGrow: 1, ml: 2 }}>
            Emergency Contacts
          </Typography>
        </Toolbar>
      </AppBar>

      <Container maxWidth="md" sx={{ py: 3, pb: 10 }}>
        {/* Info Card */}
        <Card sx={{ mb: 3 }}>
          <CardContent>
            <Typography variant="h6" gutterBottom>
              Your Safety Network
            </Typography>
            <Typography variant="body2" color="text.secondary">
              Add up to 5 trusted contacts who will be notified during emergencies.
              They'll receive SMS alerts with your location and status.
            </Typography>
          </CardContent>
        </Card>

        {/* Contacts List */}
        {contacts.length > 0 ? (
          <Card>
            <CardContent>
              <Typography variant="h6" gutterBottom>
                Emergency Contacts ({contacts.length}/5)
              </Typography>
              <List>
                {contacts.map((contact, index) => (
                  <ListItem
                    key={contact._id || index}
                    divider={index < contacts.length - 1}
                  >
                    <Avatar sx={{ mr: 2, bgcolor: 'primary.main' }}>
                      <Person />
                    </Avatar>
                    <ListItemText
                      primary={
                        <Box display="flex" alignItems="center" gap={1}>
                          <Typography variant="subtitle1">
                            {contact.name}
                          </Typography>
                          <Chip
                            label={contact.relationship}
                            size="small"
                            color={getRelationshipColor(contact.relationship)}
                          />
                        </Box>
                      }
                      secondary={
                        <Box display="flex" alignItems="center" gap={1} mt={0.5}>
                          <Phone sx={{ fontSize: 16 }} />
                          <Typography variant="body2">
                            {contact.phone}
                          </Typography>
                        </Box>
                      }
                    />
                    <ListItemSecondaryAction>
                      <IconButton
                        edge="end"
                        onClick={() => handleEditContact(contact)}
                        sx={{ mr: 1 }}
                      >
                        <Edit />
                      </IconButton>
                      <IconButton
                        edge="end"
                        onClick={() => handleDeleteContact(contact)}
                        color="error"
                      >
                        <Delete />
                      </IconButton>
                    </ListItemSecondaryAction>
                  </ListItem>
                ))}
              </List>
            </CardContent>
          </Card>
        ) : (
          <Card>
            <CardContent sx={{ textAlign: 'center', py: 6 }}>
              <Person sx={{ fontSize: 60, color: 'text.secondary', mb: 2 }} />
              <Typography variant="h6" gutterBottom>
                No Emergency Contacts
              </Typography>
              <Typography variant="body2" color="text.secondary" mb={3}>
                Add trusted contacts who will be notified during emergencies
              </Typography>
              <Button
                variant="contained"
                startIcon={<Add />}
                onClick={handleAddContact}
              >
                Add First Contact
              </Button>
            </CardContent>
          </Card>
        )}
      </Container>

      {/* Add Contact FAB */}
      {contacts.length > 0 && contacts.length < 5 && (
        <Fab
          color="primary"
          sx={{
            position: 'fixed',
            bottom: 16,
            right: 16,
          }}
          onClick={handleAddContact}
        >
          <Add />
        </Fab>
      )}

      {/* Add/Edit Contact Dialog */}
      <Dialog open={dialogOpen} onClose={() => setDialogOpen(false)} maxWidth="sm" fullWidth>
        <DialogTitle>
          {editingContact ? 'Edit Contact' : 'Add Emergency Contact'}
        </DialogTitle>
        <DialogContent>
          <TextField
            fullWidth
            name="name"
            label="Full Name"
            value={formData.name}
            onChange={handleInputChange}
            margin="normal"
            required
          />
          <TextField
            fullWidth
            name="phone"
            label="Phone Number"
            value={formData.phone}
            onChange={handleInputChange}
            margin="normal"
            required
            placeholder="+1234567890"
            helperText="Include country code (e.g., +1 for US)"
          />
          <TextField
            fullWidth
            select
            name="relationship"
            label="Relationship"
            value={formData.relationship}
            onChange={handleInputChange}
            margin="normal"
            required
          >
            {relationships.map((option) => (
              <MenuItem key={option} value={option}>
                {option}
              </MenuItem>
            ))}
          </TextField>
        </DialogContent>
        <DialogActions>
          <Button onClick={() => setDialogOpen(false)}>Cancel</Button>
          <Button
            onClick={handleSubmit}
            variant="contained"
            disabled={isLoading || !formData.name.trim() || !formData.phone.trim()}
          >
            {editingContact ? 'Update' : 'Add'} Contact
          </Button>
        </DialogActions>
      </Dialog>

      {/* Delete Confirmation Dialog */}
      <Dialog open={deleteDialog} onClose={() => setDeleteDialog(false)}>
        <DialogTitle>Delete Contact</DialogTitle>
        <DialogContent>
          <Typography>
            Are you sure you want to remove {contactToDelete?.name} from your emergency contacts?
          </Typography>
        </DialogContent>
        <DialogActions>
          <Button onClick={() => setDeleteDialog(false)}>Cancel</Button>
          <Button onClick={confirmDelete} color="error" variant="contained">
            Delete
          </Button>
        </DialogActions>
      </Dialog>
    </Box>
  );
};

export default EmergencyContacts;
